-- Recreate live Comunhao integrity constraints in the isolated schema.
BEGIN;
SET LOCAL search_path = comunhao, public, auth, extensions;
CREATE TABLE IF NOT EXISTS core.migration_constraint_issues (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  migration_name text NOT NULL,
  table_name text NOT NULL,
  constraint_name text NOT NULL,
  error_message text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
DELETE FROM core.migration_constraint_issues WHERE migration_name = '308_comunhao_live_constraints';
DO $constraints$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint con
    JOIN pg_class c ON c.oid = con.conrelid
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'comunhao'
      AND c.relname = 'administrative_requests'
      AND con.conname = 'administrative_requests_pkey'
  ) THEN
    BEGIN
      EXECUTE $ddl1$ALTER TABLE comunhao."administrative_requests" ADD CONSTRAINT "administrative_requests_pkey" PRIMARY KEY (id)$ddl1$;
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO core.migration_constraint_issues (
        migration_name, table_name, constraint_name, error_message
      ) VALUES ('308_comunhao_live_constraints', 'administrative_requests', 'administrative_requests_pkey', SQLERRM);
